import{_ as t,o as s,c as a,a3 as i}from"./chunks/framework.Cr9EE2ob.js";const g=JSON.parse('{"title":"Testing","description":"There are two smoke binaries, and which one to reach for depends on the question. They are not alternatives.","frontmatter":{"head":[["meta",{"name":"robots","content":"noindex"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/main/operations/testing.html"}],["meta",{"property":"og:title","content":"Testing"}],["meta",{"name":"twitter:title","content":"Testing"}],["meta",{"property":"og:description","content":"There are two smoke binaries, and which one to reach for depends on the question. They are not alternatives."}],["meta",{"name":"twitter:description","content":"There are two smoke binaries, and which one to reach for depends on the question. They are not alternatives."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/main/operations/testing.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/main/operations/testing.html\\",\\"headline\\":\\"Testing\\",\\"description\\":\\"There are two smoke binaries, and which one to reach for depends on the question. They are not alternatives.\\",\\"dateModified\\":\\"2026-10-23T17:25:06.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/main/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Testing\\",\\"item\\":\\"https://doc.yarilomail.org/main/operations/testing.html\\"}]}]}"]]},"headers":[],"relativePath":"operations/testing.md","filePath":"operations/testing.md","lastUpdated":1792776306000}'),n={name:"operations/testing.md"};function o(r,e,l,h,d,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h1><h2 id="smoke-tests" tabindex="-1">Smoke tests <a class="header-anchor" href="#smoke-tests" aria-label="Permalink to &quot;Smoke tests&quot;">​</a></h2><p>There are two smoke binaries, and which one to reach for depends on the question. They are not alternatives.</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">question it answers</th><th style="text-align:left;">how it is run</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://github.com/yarilomail/yarilo/tree/main/app/smoketest" target="_blank" rel="noreferrer"><code>app/<wbr>smoketest</code></a></td><td style="text-align:left;">is <em>this deployment</em> serving correctly?</td><td style="text-align:left;">against a live cluster, per rollout — <code>smoke.<wbr>yml</code>, or by hand</td></tr><tr><td style="text-align:left;"><a href="https://github.com/yarilomail/yarilo/tree/main/app/smoketest-e2e" target="_blank" rel="noreferrer"><code>app/<wbr>smoketest-e2e</code></a></td><td style="text-align:left;">does mail get in and out at all?</td><td style="text-align:left;">against any yarilo — local binary, compose, or staging</td></tr></tbody></table><p><strong><code>app/<wbr>smoketest</code></strong> is the per-rollout gate: telemetry <code>/<wbr>healthz</code> and <code>/<wbr>readyz</code>, the POP3S greeting, ManageSieve, Sieve execution, quota and ACL, FTS, and the JMAP checks including the header forms. It checks a deployment.</p><p><strong><code>app/<wbr>smoketest-e2e</code></strong> drives the whole happy path in one pass — Submission AUTH over STARTTLS, LMTP delivery, then reading the same message back over both IMAPS and POP3S, with each protocol&#39;s native and SASL authentication. It checks that the parts fit together, which the per-rollout checks do not: each of those looks at one listener.</p><p>It needs a seeded account, and both the seeding and the invocation are in <strong><a href="/main/operations/smoke.html">End-to-end smoke test</a></strong>, which is also where the step-by-step table lives.</p><p>IMAP conformance is exercised separately on the stand with an external conformance tester.</p><h3 id="run-via-github-actions" tabindex="-1">Run via GitHub Actions <a class="header-anchor" href="#run-via-github-actions" aria-label="Permalink to &quot;Run via GitHub Actions&quot;">​</a></h3><p>Trigger <code>smoke.<wbr>yml</code> (<code>workflow_<wbr>dispatch</code>) with:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Input</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>host</code></td><td style="text-align:left;">yarilo hostname, e.g. <code>mail-sb.<wbr>seconddns.<wbr>com</code></td></tr><tr><td style="text-align:left;"><code>imap_<wbr>port</code></td><td style="text-align:left;">IMAPS port (default <code>993</code>)</td></tr><tr><td style="text-align:left;"><code>pop3s_<wbr>port</code></td><td style="text-align:left;">POP3S port (leave empty to skip)</td></tr><tr><td style="text-align:left;"><code>telemetry_<wbr>url</code></td><td style="text-align:left;">Telemetry base URL, e.g. <code>http:/<wbr>/<wbr>10.<wbr>0.<wbr>0.<wbr>1:8080</code></td></tr><tr><td style="text-align:left;"><code>insecure</code></td><td style="text-align:left;">Skip TLS cert verification (<code>true</code>/<code>false</code>)</td></tr><tr><td style="text-align:left;"><code>director_<wbr>api</code></td><td style="text-align:left;">Director admin API base URL; empty skips the director check. Reachable only from an in-cluster or port-forwarded runner</td></tr></tbody></table><p>The accounts come from repository <strong>variables</strong>, their passwords and the director token from <strong>secrets</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SMOKE_<wbr>IMAP_<wbr>USER</code></td><td style="text-align:left;">IMAP test account, e.g. <code>u1@d00001.<wbr>test</code></td></tr><tr><td style="text-align:left;"><code>SMOKE_<wbr>QUOTA_<wbr>OVER_<wbr>USER</code></td><td style="text-align:left;">account kept over quota, for the over-quota checks</td></tr><tr><td style="text-align:left;"><code>SMOKE_<wbr>ACL_<wbr>PEER_<wbr>USER</code></td><td style="text-align:left;">second account, for the ACL checks</td></tr><tr><td style="text-align:left;"><code>SMOKE_<wbr>ACL_<wbr>SHARED_<wbr>PREFIX</code></td><td style="text-align:left;">the namespace prefix the ACL checks share through</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">Secret</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SMOKE_<wbr>IMAP_<wbr>PASS</code></td><td style="text-align:left;">password of <code>SMOKE_<wbr>IMAP_<wbr>USER</code></td></tr><tr><td style="text-align:left;"><code>SMOKE_<wbr>QUOTA_<wbr>OVER_<wbr>PASS</code></td><td style="text-align:left;">password of <code>SMOKE_<wbr>QUOTA_<wbr>OVER_<wbr>USER</code></td></tr><tr><td style="text-align:left;"><code>SMOKE_<wbr>ACL_<wbr>PEER_<wbr>PASS</code></td><td style="text-align:left;">password of <code>SMOKE_<wbr>ACL_<wbr>PEER_<wbr>USER</code></td></tr><tr><td style="text-align:left;"><code>SMOKE_<wbr>DIRECTOR_<wbr>API_<wbr>TOKEN</code></td><td style="text-align:left;">director admin API token</td></tr></tbody></table><h3 id="run-imaptest-manually-against-sandbox" tabindex="-1">Run imaptest manually against sandbox <a class="header-anchor" href="#run-imaptest-manually-against-sandbox" aria-label="Permalink to &quot;Run imaptest manually against sandbox&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dovecot/imaptest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  host=mail-sb.seconddns.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  port=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">993</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ssl=yes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  user=u1@d00001.test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  pass=&#39;HIDDEN&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  no_pipelining=yes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  clients=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  count=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span></code></pre></div><h3 id="reading-the-gate-report" tabindex="-1">Reading the gate report <a class="header-anchor" href="#reading-the-gate-report" aria-label="Permalink to &quot;Reading the gate report&quot;">​</a></h3><p>Most <code>app/<wbr>smoketest</code> checks are enabled by the flag that configures them: <code>-fts-user</code> enables the FTS search check, <code>-jmap</code> enables the JMAP ones. A check the run was not given credentials for is <strong>skipped, not dropped</strong> — it stays in the report by name, with the flag that would enable it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{&quot;msg&quot;:&quot;smoke: summary&quot;,&quot;checks&quot;:28,&quot;passed&quot;:19,&quot;failed&quot;:0,&quot;skipped&quot;:9}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>9 smoke check(s) skipped:</span></span>
<span class="line"><span>  - jmap session resource (/.well-known/jmap) (needs -jmap)</span></span>
<span class="line"><span>  ...</span></span></code></pre></div><p>This matters because the earlier gate counted only what it ran, and a rollout that lost a flag reported <code>11/<wbr>11</code> green with fewer checks than the one before it. A count of what ran cannot describe what was not asked for, so the report always describes the whole intended gate.</p><h3 id="demanding-the-whole-gate" tabindex="-1">Demanding the whole gate <a class="header-anchor" href="#demanding-the-whole-gate" aria-label="Permalink to &quot;Demanding the whole gate&quot;">​</a></h3><p>A deployment that expects every check to be configured says so once, instead of diffing the skipped list by hand on each rollout:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Flag</th><th style="text-align:left;">Effect</th></tr></thead><tbody><tr><td style="text-align:left;"><code>-require-all</code></td><td style="text-align:left;">a check disabled by a missing flag is a failure</td></tr><tr><td style="text-align:left;"><code>-require-all-except=&lt;areas&gt;</code></td><td style="text-align:left;">comma-separated areas <code>-require-all</code> does not demand</td></tr></tbody></table><p>Every check belongs to an area — <code>telemetry</code>, <code>smtp</code>, <code>pop3s</code>, <code>pop3</code>, <code>lmtp-login</code>, <code>managesieve</code>, <code>sieve</code>, <code>imap</code>, <code>director</code>, <code>jmap</code> — and an exemption names areas, so <code>-require-all -require-all-except=jmap</code> demands everything the deployment runs while forgiving a service it does not.</p><p>Three properties are worth knowing before relying on it:</p><ul><li>An exemption forgives <strong>an unconfigured check only</strong>. A check in an exempt area that ran and failed still fails: the flag says &quot;we do not run this&quot;, not &quot;ignore errors from here&quot;.</li><li>An area no check declares is rejected (exit 2, with the known areas listed). A misspelled area would otherwise read as a narrowed gate that quietly still demands everything.</li><li><code>-require-all-except</code> without <code>-require-all</code> is rejected for the same reason: alone it reads as &quot;demand everything except this&quot; while demanding nothing.</li></ul><p><code>components.<wbr>jmap</code> ships disabled, which is why the JMAP checks are the usual exemption — and why <code>-require-all</code> is off by default. Which areas a deployment owes is an operator decision, not a property of the binary.</p><h3 id="where-the-gate-injects-mail" tabindex="-1">Where the gate injects mail <a class="header-anchor" href="#where-the-gate-injects-mail" aria-label="Permalink to &quot;Where the gate injects mail&quot;">​</a></h3><p>The Sieve and FTS checks both need a message delivered into a user&#39;s mailbox before they can look for it, so they share one endpoint, named for that role:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Flag</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>-delivery-host</code></td><td style="text-align:left;">host that accepts the injected mail (defaults to <code>-smtp-host</code>, then <code>-host</code>)</td></tr><tr><td style="text-align:left;"><code>-delivery-port</code></td><td style="text-align:left;">port that accepts it (default <code>25</code>)</td></tr><tr><td style="text-align:left;"><code>-delivery-proto</code></td><td style="text-align:left;"><code>smtp</code> (greets with EHLO) or <code>lmtp</code> (LHLO). Default <code>smtp</code></td></tr></tbody></table><p>Set the protocol to match the listener you point at. An LMTP server answers EHLO with <code>500 5.<wbr>5.<wbr>1 This is a LMTP server, use LHLO</code>, and both checks then fail with that message rather than with anything about Sieve or search:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- sieve plugins: plugin failures:</span></span>
<span class="line"><span>    fileinto: EHLO: 500 5.5.1 This is a LMTP server, use LHLO</span></span>
<span class="line"><span>- imap FTS (SEARCH BODY/TEXT/HEADER/FROM): lmtp deliver: EHLO: 500 5.5.1 ...</span></span></code></pre></div><p>A deployment whose only ingress is <code>yarilo-lmtp-login</code> — which is what the chart ships — therefore runs both checks like this:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">smoketest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail.example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -delivery-host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yarilo-lmtp-login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -delivery-port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -delivery-proto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lmtp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -sieve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fts-user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> u1@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fts-pass</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span></span></code></pre></div><p>Delivering through submission or the MX port is equally valid and is the configuration that exercises the end-to-end path alongside the MTA; there the default <code>-delivery-proto smtp</code> is correct and nothing needs saying.</p><p>The protocol is <strong>declared, not inferred from the port number</strong>. Reading 24 as LMTP and 25 as SMTP is a guess about the topology: a site running LMTP on 2424, or submission on 587, would be greeted wrongly and told so in a message that points somewhere else. A value that is neither <code>smtp</code> nor <code>lmtp</code> stops the run rather than falling back, so a typo cannot read as a deliberate choice.</p><p><code>checkLMTPLogin</code> is separate and unaffected: it builds its own address from <code>-host</code> and <code>-lmtp-login-port</code>, because it tests the login proxy&#39;s handshake rather than delivery.</p><h2 id="what-the-deployment-gate-does-not-cover-on-purpose" tabindex="-1">What the deployment gate does not cover, on purpose <a class="header-anchor" href="#what-the-deployment-gate-does-not-cover-on-purpose" aria-label="Permalink to &quot;What the deployment gate does not cover, on purpose&quot;">​</a></h2><p><code>mailbox_<wbr>list_<wbr>storage_<wbr>escape_<wbr>char</code> is unset in the committed sandbox values, so the storage-name escaping path is not exercised by any routine rollout gate. This is deliberate, and it is written here so the gap is not later mistaken for an oversight and patched with a second mechanism.</p><p>The escaping path — and the NFC-against-escaping interaction, a form-preserving property — is covered by unit tests that assert on computed strings, plus one end-to-end IMAP test with a <code>t.<wbr>Skip</code> precondition: it needs a filesystem that does not compose names on creation, so it skips on macOS (APFS) and carries the weight on the CI runners (self-hosted Linux, which production also is). CI covers exactly what the gate no longer does.</p><p>This is the same shape as two earlier blind spots — a build tag the compiler never sees, a deployment flag the tests never run — a config key that is off by default, so the enabled path is walked nowhere routine. The resolution is the same: the discipline lives where the path is actually taken, which for escaping is the CI unit and skip-guarded integration tests, not the sandbox gate.</p><p>If deployment-level coverage is ever wanted, the cheap way is not to enable escaping in the committed values — it changes on-disk names for every folder — but to add one gate run with <code>--set storage.<wbr>mailbox_<wbr>list_<wbr>storage_<wbr>escape_<wbr>char=^</code> alongside the default run.</p><h2 id="a-tagged-run-is-tree-wide-or-it-is-not-a-tagged-run" tabindex="-1">A tagged run is tree-wide, or it is not a tagged run <a class="header-anchor" href="#a-tagged-run-is-tree-wide-or-it-is-not-a-tagged-run" aria-label="Permalink to &quot;A tagged run is tree-wide, or it is not a tagged run&quot;">​</a></h2><p><code>go test .<wbr>/<wbr>.<wbr>.<wbr>.</code> does not compile code behind a build tag at all, so a green plain run says nothing about the tagged one. Both are required before a change lands:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>go test ./... -count=1</span></span>
<span class="line"><span>go test -tags flatcurve ./... -count=1</span></span></code></pre></div><p>The second must cover the <strong>whole tree</strong>, not the package being edited. Tagged code is not confined to the engine package: its consumers and the benchmark harness are behind the same tag, and their fixtures are where a changed contract surfaces. Keying the FTS index path by the folder GUID passed a tagged run of <code>internal/<wbr>fts/<wbr>flatcurve</code> and failed CI on five fixtures elsewhere that built a mailbox reference with no GUID, plus a test that computed the shard path with the layout the change had just removed. Those are exactly the places a package-scoped run cannot reach.</p><h2 id="load-tests" tabindex="-1">Load tests <a class="header-anchor" href="#load-tests" aria-label="Permalink to &quot;Load tests&quot;">​</a></h2><p><a href="https://github.com/yarilomail/yarilo-loadtest" target="_blank" rel="noreferrer">yarilo-loadtest</a> is the load generator: LMTP delivery and persistent IMAP sessions, with a configurable corpus. It is separate from the smoke tests, which answer &quot;is it up&quot;; this answers &quot;what does it cost&quot;.</p><p>Six Jobs in <a href="https://github.com/yarilomail/yarilo/tree/main/hack/loadtest/" target="_blank" rel="noreferrer"><code>hack/<wbr>loadtest/</code></a>, each for a different question:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Job</th><th style="text-align:left;">Drives</th><th style="text-align:left;">Read alongside</th></tr></thead><tbody><tr><td style="text-align:left;"><code>lmtp-job.<wbr>yaml</code></td><td style="text-align:left;">delivery, and through it FTS indexing</td><td style="text-align:left;"><code>fts_<wbr>build_<wbr>stage_<wbr>seconds</code>, <code>fts_<wbr>worker_<wbr>busy_<wbr>seconds_<wbr>total</code>, <code>fts_<wbr>index_<wbr>queue_<wbr>depth</code></td></tr><tr><td style="text-align:left;"><code>imap-job.<wbr>yaml</code></td><td style="text-align:left;">persistent sessions: append, fetch, store, expunge</td><td style="text-align:left;">per-command percentiles from the run&#39;s own summary</td></tr><tr><td style="text-align:left;"><code>search-job.<wbr>yaml</code></td><td style="text-align:left;">SEARCH only, against an index the others filled</td><td style="text-align:left;">search latency without append traffic competing for the same per-user index</td></tr><tr><td style="text-align:left;"><code>jmap-job.<wbr>yaml</code></td><td style="text-align:left;">the read chain a client opens with: session, <code>Mailbox/<wbr>get</code>, <code>Email/<wbr>query</code>+<code>get</code></td><td style="text-align:left;">per-method latency, and <code>nr_<wbr>throttled</code> beside it</td></tr><tr><td style="text-align:left;"><code>pop3-job.<wbr>yaml</code></td><td style="text-align:left;">full POP3 sessions: connect, authenticate, survey, retrieve, quit</td><td style="text-align:left;">per-command latency, and the maildrop lock under concurrency</td></tr><tr><td style="text-align:left;"><code>lmtp-mbox-job.<wbr>yaml</code></td><td style="text-align:left;">delivery of a <strong>non-English</strong> corpus</td><td style="text-align:left;"><code>fts_<wbr>build_<wbr>stage_<wbr>seconds</code> in a language whose stopword list actually changed</td></tr></tbody></table><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hack/loadtest/lmtp-job.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yarilo-sb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> job/yarilo-loadtest-lmtp</span></span></code></pre></div><p><strong>The JMAP job measures the read path and does not check protocol behaviour.</strong> The driver asks for <code>id</code>, <code>subject</code>, <code>from</code>, <code>receivedAt</code> and <code>threadId</code>, so nothing in a load run exercises the <code>header:*</code> forms or property validation. Those want a conformance check; a load run that happened to pass would say nothing about them.</p><p>And for JMAP in particular, read <a href="#check-for-cpu-throttling-before-believing-a-latency-number">the throttling section</a> first. A 5085 ms median once looked like an algorithmic defect and was a 500m CPU limit.</p><h3 id="measuring-a-language-other-than-english" tabindex="-1">Measuring a language other than English <a class="header-anchor" href="#measuring-a-language-other-than-english" aria-label="Permalink to &quot;Measuring a language other than English&quot;">​</a></h3><p>The generator emits English, and the English stopword list was the one already correct — 174 words matching its source exactly, unchanged by the stopword changes. A sandbox run therefore shows <strong>nothing</strong> for those changes, by construction rather than by measurement.</p><p><code>lmtp-mbox-job.<wbr>yaml</code> replays a corpus in a language whose list did change. Build it from yarilo&#39;s own lists:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hack/loadtest/corpus/gen-corpus.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 250</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/uk.mbox</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yarilo-sb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configmap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> loadtest-corpus</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --from-file=corpus.mbox=/tmp/uk.mbox</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run=client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yaml</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hack/loadtest/lmtp-mbox-job.yaml</span></span></code></pre></div><p><strong>The function words come from the server&#39;s own stopword lists</strong>, so the corpus and the server cannot disagree about what a stopword is. The content words are pairs of function words run together — deterministic, valid UTF-8 in the same script, and not in the list. That is deliberate: what is being measured is how many tokens survive filtering and what they cost to stem, and inventing prose would put an unstated word-frequency distribution into a number that is supposed to be about the filter. The ratio is stated rather than incidental — <code>STOPWORD_<wbr>RATIO</code> of every ten words, four by default, which is roughly what running text carries.</p><p>Two limits worth knowing before you meet them: a <strong>ConfigMap holds about 1 MiB</strong>, and <strong>SMTP carries at most 1000 octets per line</strong> including the CRLF — a server given a longer one rejects the whole transaction, so one unwrapped line fails every delivery in the run. The generator wraps at nine words; the loader refuses a file that breaks the limit and names the message, line and length.</p><h3 id="reading-the-result" tabindex="-1">Reading the result <a class="header-anchor" href="#reading-the-result" aria-label="Permalink to &quot;Reading the result&quot;">​</a></h3><p>The summary has an <code>errors</code> column and a <code>cancel</code> column. <strong><code>errors</code> means the server did something wrong; <code>cancel</code> counts operations the run cut off when <code>-duration</code> expired</strong> — roughly one per client, so a clean run reports something like <code>0 errors, 8 cancelled at the deadline</code>. Any non-zero <code>errors</code> is a finding.</p><p>The live table prints one line per interval rather than a running total, because a rate that collapses at forty seconds and a rate that was never good average to the same number.</p><h3 id="choices-in-the-manifests-that-are-not-incidental" tabindex="-1">Choices in the manifests that are not incidental <a class="header-anchor" href="#choices-in-the-manifests-that-are-not-incidental" aria-label="Permalink to &quot;Choices in the manifests that are not incidental&quot;">​</a></h3><p><strong>The corpus is 20 KB–1 MB with half the messages carrying an attachment.</strong> Tokenisation cost scales with body size, so a corpus of small plain-text notes reports a per-message cost no real deployment sees.</p><p><strong>The seed is fixed.</strong> Two runs against different versions then compare the server rather than the corpus.</p><p><strong>Recipients span <code>u1.<wbr>.<wbr>u150</code></strong>, which covers all three mailbox types in the sandbox — mdbox <code>u1-50</code>, maildir <code>u51-100</code>, sdbox <code>u101-150</code>. A run confined to one type measures that type.</p><p><strong><code>-msgs</code> is a steady state, not a total.</strong> Without it the mailboxes grow through the whole run, so the same operation costs more at the end than at the start. <code>-msgs=0</code> turns it off, which is what the search-only Job needs.</p><p><strong>POP3 opens and closes a session per iteration</strong>, which is the protocol rather than a shortcut: the server locks the maildrop for the length of a session, so a generator that held its connections would measure its own lock contention and report it as the server&#39;s. <code>-delete</code> stays off — it consumes the mailboxes every other run measures against.</p><p><strong><code>-mailboxes-per-user=4</code></strong> produces the condition worth testing against a server that dispatches index work per user: more than one mailbox of one user wanting a pass at the same time.</p><h3 id="check-for-cpu-throttling-before-believing-a-latency-number" tabindex="-1">Check for CPU throttling before believing a latency number <a class="header-anchor" href="#check-for-cpu-throttling-before-believing-a-latency-number" aria-label="Permalink to &quot;Check for CPU throttling before believing a latency number&quot;">​</a></h3><p><strong>Do this first, every time.</strong> A container at its CPU limit produces latencies that look exactly like a defect in the code, and no amount of profiling the code will find them — the profile shows the work spread over wall-clock time that the scheduler took away.</p><p>This is not hypothetical. JMAP read latency was measured at 5085 ms median and investigated as an algorithmic problem, complete with a benchmark and three proposed redesigns. The container had <code>limits.<wbr>cpu: 500m</code> and was consuming ~450m of it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nr_periods 2226 · nr_throttled 1806 · throttled_usec 286912352</span></span></code></pre></div><p>81% of scheduler periods stopped. Raising the limit and changing nothing else:</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:right;"><code>cpu: 500m</code></th><th style="text-align:right;"><code>cpu: 3</code></th></tr></thead><tbody><tr><td style="text-align:left;"><code>Email/<wbr>query</code>+<code>get</code> median</td><td style="text-align:right;">5085 ms</td><td style="text-align:right;"><strong>322.9 ms</strong></td></tr><tr><td style="text-align:left;"><code>Mailbox/<wbr>get</code> median</td><td style="text-align:right;">1103 ms</td><td style="text-align:right;">132.2 ms</td></tr><tr><td style="text-align:left;">throughput</td><td style="text-align:right;">1.2 ops/s</td><td style="text-align:right;">15.3 ops/s</td></tr><tr><td style="text-align:left;"><code>nr_<wbr>throttled</code></td><td style="text-align:right;">1806 / 2226</td><td style="text-align:right;">0 / 840</td></tr></tbody></table><p>A fifteen-fold difference from a value in <code>values.<wbr>yaml</code>.</p><p>Read it from inside the container — cgroup v2 exposes it directly:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">n</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">po</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">containe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup/cpu.stat</span></span></code></pre></div><p><code>nr_<wbr>throttled</code> against <code>nr_<wbr>periods</code> is the whole answer. Anything above a few percent means the numbers beside it describe the quota, not the server.</p><p>The kubelet also exports <code>container_<wbr>cpu_<wbr>cfs_<wbr>throttled_<wbr>periods_<wbr>total</code> per container via cAdvisor:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --raw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/api/v1/nodes/&lt;node&gt;/proxy/metrics/cadvisor&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container_cpu_cfs_throttled_periods_total</span></span></code></pre></div><p><strong>But nothing scrapes it.</strong> The cluster runs metrics-server only, with no Prometheus, so this is available on demand and not in history — there is no answering &quot;was it throttled during yesterday&#39;s run&quot; after the fact. Take the reading while the run is going, or record it with the result.</p><h3 id="profiling-under-load" tabindex="-1">Profiling under load <a class="header-anchor" href="#profiling-under-load" aria-label="Permalink to &quot;Profiling under load&quot;">​</a></h3><p>A load run is when the profilers are worth having. With <code>telemetry.<wbr>pprof.<wbr>enabled</code> set (see <a href="/main/installation/deployment.html#profiling-a-live-pod">Deployment</a>), start a Job, then:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yarilo-sb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port-forward</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yarilo-backend-0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8085:8085</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # the fts container&#39;s telemetry port</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pprof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -http=:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://localhost:8085/debug/pprof/profile?seconds=30&quot;</span></span></code></pre></div><p>Take the profile while the Job is running, not after — an idle process profiles its idle loop, which is a picture of nothing.</p><p>And read <code>cpu.<wbr>stat</code> in the same window. A profile taken through throttling attributes the work correctly and the <em>time</em> misleadingly: the shares are real, the seconds are the quota&#39;s.</p>`,87)])])}const k=t(n,[["render",o]]);export{g as __pageData,k as default};
